{
  "gateway": "google_ads_native_action",
  "mode": "direct",
  "description": "Complete Google Ads API v23 native gateway: all 171 checked-in service RPCs plus every mapper-backed compatibility action, inside one bounded MCP tool. Use LIST_ACTIONS or DESCRIBE_ACTION; URI/query/body fields are routed automatically.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Canonical v23 RPC action, LIST_ACTIONS, or DESCRIBE_ACTION."
      },
      "target_action": {
        "type": "string",
        "description": "Action to describe when action=DESCRIBE_ACTION."
      },
      "account_id": {
        "type": "string",
        "description": "Authorized Google Ads customer ID. Required for execution."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Native URI-template fields such as resource_name. customer_id may be omitted because account_id is authoritative."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "default": {},
        "description": "Native request fields. The mapper routes URI fields to the path and remaining fields to query/body from the v23 proto."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query-string fields. Normally params is enough."
      },
      "payload": {
        "$ref": "#/properties/path_params",
        "default": {},
        "description": "Native Google Ads v23 request body fields."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required when the selected RPC deletes, removes, books, moves, ends, or changes billing."
      },
      "dry_run": {
        "type": "boolean",
        "description": "Writes default to true. Set false to execute after validating the exact v23 request."
      },
      "idempotency_key": {
        "type": "string",
        "format": "uuid",
        "description": "Recommended for write RPCs."
      },
      "service": {
        "type": "string",
        "description": "LIST_ACTIONS filter by proto service name."
      },
      "read_only": {
        "type": "boolean",
        "description": "LIST_ACTIONS filter."
      },
      "search": {
        "type": "string",
        "description": "LIST_ACTIONS case-insensitive action/service/RPC filter."
      },
      "surface": {
        "type": "string",
        "enum": [
          "all",
          "rpc",
          "legacy"
        ],
        "default": "all",
        "description": "LIST_ACTIONS catalog surface."
      },
      "limit": {
        "type": "integer",
        "exclusiveMinimum": 0,
        "maximum": 500,
        "default": 50,
        "description": "LIST_ACTIONS result limit."
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "default": 0,
        "description": "LIST_ACTIONS result offset."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": true,
    "$schema": "http://json-schema.org/draft-07/schema#"
  },
  "rpc_action_count": 171,
  "usage": "Call google_ads_native_action with action=LIST_ACTIONS for RPC and compatibility actions, or use whathead_tool_help with operation=<canonical v23 action> for exact native fields."
}
